let comparisons = 0;

export function countComparison() {
  comparisons += 1;
}

export function comparisonCount() {
  return comparisons;
}

export function resetComparisons() {
  comparisons = 0;
}

import { countComparison } from './instrument.js';

export function findDuplicates(items) {
  const duplicates = [];
  for (let i = 0; i < items.length; i += 1) {
    let count = 0;
    for (let j = 0; j < items.length; j += 1) {
      countComparison();
      if (items[j] === items[i]) count += 1;
    }
    if (count > 1 && !duplicates.includes(items[i])) duplicates.push(items[i]);
  }
  return duplicates;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { findDuplicates } from '../src/find-duplicates.js';

test('reports each duplicate once, in first-appearance order', () => {
  assert.deepEqual(findDuplicates(['a', 'b', 'a', 'c', 'b']), ['a', 'b']);
});

test('returns empty for unique lists', () => {
  assert.deepEqual(findDuplicates(['x', 'y', 'z']), []);
});

test('order pins to first appearance, not second occurrence', () => {
  assert.deepEqual(findDuplicates(['a', 'b', 'b', 'a']), ['a', 'b']);
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { findDuplicates } from '../src/find-duplicates.js';
import { comparisonCount, resetComparisons } from '../src/instrument.js';

// Independent reference: each duplicated value once, first-appearance order.
function referenceDuplicates(items) {
  const counts = new Map();
  for (const item of items) counts.set(item, (counts.get(item) ?? 0) + 1);
  const out = [];
  const added = new Set();
  for (const item of items) {
    if ((counts.get(item) ?? 0) > 1 && !added.has(item)) {
      added.add(item);
      out.push(item);
    }
  }
  return out;
}

// 1) Results identical to reference on small pinned cases.
assert.deepEqual(findDuplicates(['a', 'b', 'a', 'c', 'b']), ['a', 'b']);
assert.deepEqual(findDuplicates([]), []);
assert.deepEqual(findDuplicates(['a', 'b', 'b', 'a']), ['a', 'b']);

// 2) Deterministic 200-item workload: results equal reference AND the
// instrumented op-count is under the stated budget (seeded code: 40000).
const items = [];
for (let i = 0; i < 200; i += 1) items.push('v' + ((i * 7) % 149));
resetComparisons();
const result = findDuplicates(items);
assert.deepEqual(result, referenceDuplicates(items), 'results changed - speed that changes answers is a bug');
console.log('PERF_OPTIMIZATION_ORACLE results ok');
const ops = comparisonCount();
assert.ok(
  ops <= 2000,
  'findDuplicates on 200 items performed ' + ops + ' instrumented comparisons - the budget is 2000 and the seeded code did 40000',
);
console.log('PERF_OPTIMIZATION_ORACLE ops ' + ops + ' within budget');

// 3) The whole suite is green on the optimized tree (real run).
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(process.cwd()), 0, 'the suite must be green on the optimized tree');
console.log('PERF_OPTIMIZATION_ORACLE suite green');
console.log('PERF_OPTIMIZATION_ORACLE done');
